package dev.kelmagic.client;
import dev.kelmagic.*;import dev.kelmagic.core.*;import dev.kelmagic.network.*;import dev.kelmagic.research.*;
import java.util.*;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.*;import net.neoforged.neoforge.network.PacketDistributor;
/** A small book, side bookmarks, and single-owner research maps. */
public final class CodexScreen extends Screen {
 static final String[] TABS={"words","origins","materials","sound","equipment","writing","great","home","infusion"};
 static final String[] LABELS={"Слова Кэл","Первые носители","Материалы","Отзвук","Одеяния","Медная письменность","Великие высказывания","Добро пожаловать","Наполнение"};
 static final String[] ICONS={"ancient_manuscript","mana_core","golden_thread","cassette","arcane_helmet","minecraft:copper_ingot","dragon_heart","minecraft:book","resonance_station"};
 private TableBookView tableView;
 public TableBookView tableView(){return tableView;}
 public CodexScreen(CodexOpen p,TableBookView view){this(p);this.tableView=view;}
 private final Set<String> known;private final List<String> notes;private final boolean offhand;private final String token;
 private static final List<String> WORDS=new ArrayList<>(KelLexicon.WORDS.keySet());
 private float uiScale=1;private double zoom=1;private int sort;private boolean knownOnly;private final Map<Integer,Double> zooms=new HashMap<>();private int section=7,page,x,y,panX,panY;private String query="";private EditBox note;private boolean dragging;
 private final Map<Integer,int[]> pans=new HashMap<>();private final Map<Integer,int[]> bookmarkRects=new HashMap<>();
 public CodexScreen(CodexOpen p){super(Component.translatable("kelmagic.codex_title"));known=new HashSet<>(p.words());notes=new ArrayList<>(p.notes());while(notes.size()<WORDS.size())notes.add("");offhand=p.offhand();token=p.token();page=Math.clamp(p.page(),0,WORDS.size()-1);query=p.query();sort=Math.clamp(p.sort(),0,1);knownOnly=p.knownOnly();section=p.section()==7?7:tabVisible(p.section())?p.section():1;ensureWord();}
 public static void open(CodexOpen p){Minecraft.getInstance().setScreen(new CodexScreen(p));}
 public void updateTableBook(net.minecraft.world.item.ItemStack book){if(tableView==null)return;var words=new HashSet<>(dev.kelmagic.item.CodexItem.knownWords(book));List<String> incoming=book.getOrDefault(MagicComponents.CODEX_NOTES.get(),List.<String>of());var nextNotes=new ArrayList<>(incoming);while(nextNotes.size()<WORDS.size())nextNotes.add("");if(known.equals(words)&&notes.equals(nextNotes))return;known.clear();known.addAll(words);notes.clear();notes.addAll(nextNotes);note=null;ensureWord();rebuildWidgets();}
 public void researchChanged(){saveNote();if(section!=7&&!tabVisible(section))section=1;rebuildWidgets();}
 boolean tabVisible(int index){return index>=0&&index<9&&index!=7&&(index==1||tableView!=null&&(index==0||index==5)&&!known.isEmpty()||ResearchClient.state.tabs().contains(TABS[index]));}
 public void selectSection(int target){if(tableView!=null){tableView.turn(true,Integer.compare(target,section),()->selectSectionNow(target));return;}selectSectionNow(target);}
 private void selectSectionNow(int target){if(tableView!=null)tableView.showCodex(this);saveNote();note=null;pans.put(section,new int[]{panX,panY});zooms.put(section,zoom);section=target;zoom=zooms.getOrDefault(target,1.0);var p=pans.getOrDefault(target,new int[]{0,0});panX=p[0];panY=p[1];dragging=false;rebuildWidgets();}
 @Override protected void init(){uiScale=Math.min(1,Math.min((width-8)/406f,(height-8)/216f));x=((int)(width/uiScale)-CodexPaint.W)/2;y=((int)(height/uiScale)-CodexPaint.H)/2;addBookmarks();if(section==0)initWords();}
 private void addBookmarks(){bookmarkRects.clear();for(int index:new int[]{0,1,2,3,4,5,6,8}){if(!tabVisible(index))continue;int slot=index<=2?index:index==8?4:index-3;int bx=index<=2?x-21:x+355,by=y+18+slot*34;bookmarkRects.put(index,new int[]{bx,by});final int target=index;addRenderableWidget(CodexPaint.ribbon(font,ICONS[target],LABELS[target],bx,by,index,()->selectSection(target),()->target==section,tableView!=null));}}
 public void renderTableBookmarks(GuiGraphics g,int mx,int my,float partial){for(var widget:renderables)if(widget instanceof Button b&&bookmarkRects.values().stream().anyMatch(r->b.getX()==r[0]&&b.getY()==r[1]))b.render(g,mx,my,partial);}
 public boolean clickTableBookmark(double mx,double my){for(var entry:bookmarkRects.entrySet()){var r=entry.getValue();if(mx>=r[0]&&mx<r[0]+25&&my>=r[1]&&my<r[1]+30){selectSection(entry.getKey());return true;}}return false;}
 private List<Integer> wordOrder(){var order=new ArrayList<Integer>();for(int i=0;i<WORDS.size();i++)if(!knownOnly||known.contains(WORDS.get(i)))order.add(i);order.sort(sort==1?Comparator.<Integer>comparingInt(i->WordRarity.of(WORDS.get(i)).ordinal()).thenComparing(i->WORDS.get(i)):Comparator.comparing(i->WORDS.get(i)));return order;}
 private void ensureWord(){var order=wordOrder();if(!order.isEmpty()&&!order.contains(page))page=order.getFirst();}
 private void changeWordView(){saveNote();note=null;ensureWord();rebuildWidgets();}
 private void initWords(){ensureWord();addRenderableWidget(CodexPaint.button(font,sort==0?"А–Я":"Редкость",x+20,y+8,74,16,()->{sort=1-sort;changeWordView();}));addRenderableWidget(CodexPaint.button(font,knownOnly?"Известные":"Все слова",x+234,y+8,106,16,()->{knownOnly=!knownOnly;changeWordView();}));addRenderableWidget(CodexPaint.button(font,"‹",x+20,y+188,28,16,()->turnWord(-1)));addRenderableWidget(CodexPaint.button(font,"›",x+312,y+188,28,16,()->turnWord(1)));var search=new EditBox(font,x+58,y+188,116,16,Component.literal("Найти слово"));search.setMaxLength(40);search.setValue(query);search.setHint(Component.literal("Слово…"));search.setResponder(v->query=v);addRenderableWidget(search);addRenderableWidget(CodexPaint.button(font,"Найти",x+247,y+188,55,16,()->{query=search.getValue().strip().toLowerCase(Locale.ROOT);for(int i:wordOrder()){String w=WORDS.get(i);if(known.contains(w)&&(w.equals(query)||KelLexicon.WORDS.get(w).translation().toLowerCase(Locale.ROOT).contains(query))){saveNote();page=i;note=null;rebuildWidgets();return;}}search.setTextColor(0xFFAA3333);}));if(tableView==null&&known.contains(WORDS.get(page))){note=new EditBox(font,x+196,y+119,136,18,Component.literal("Моя интерпретация"));note.setMaxLength(240);note.setBordered(false);note.setTextShadow(false);note.setTextColor(0xFF493427);note.setValue(notes.get(page));addRenderableWidget(note);addRenderableWidget(CodexPaint.button(font,"Записать мысль",x+215,y+159,116,18,this::saveNote));}}
 private void turnWord(int step){if(tableView!=null){tableView.turn(false,step,()->turnWordNow(step));return;}turnWordNow(step);}
 private void turnWordNow(int step){saveNote();note=null;var order=wordOrder();if(!order.isEmpty())page=order.get(Math.floorMod(order.indexOf(page)+step,order.size()));rebuildWidgets();}
 private void saveNote(){if(tableView==null&&note!=null&&known.contains(WORDS.get(page))){notes.set(page,note.getValue());PacketDistributor.sendToServer(new CodexNote(offhand,WORDS.get(page),note.getValue()));}}
 @Override public void render(GuiGraphics g,int mx,int my,float partial){if(tableView==null)renderBackground(g,mx,my,partial);g.pose().pushPose();g.pose().scale(uiScale,uiScale,1);mx=(int)(mx/uiScale);my=(int)(my/uiScale);long now=System.currentTimeMillis();if(section==0)g.blit(ResourceLocation.fromNamespaceAndPath(KelMagic.MODID,"textures/gui/codex_words.png"),x,y,0,0,360,216,360,216);else CodexPaint.book(g,x,y);if(section==0){CodexPaint.dust(g,x,y,now);renderWords(g,mx,my);}else if(section==7){CodexPaint.dust(g,x,y,now);renderWelcome(g);}else renderMap(g,mx,my,now);for(var widget:renderables)widget.render(g,mx,my,partial);for(var t:bookmarkRects.entrySet()){var r=t.getValue();if(mx>=r[0]&&mx<r[0]+25&&my>=r[1]&&my<r[1]+34)tooltip(g,List.of(Component.literal(LABELS[t.getKey()])),mx,my);}g.pose().popPose();}
 private void text(GuiGraphics g,String v,int dx,int dy,int w,int lines){CodexPaint.text(g,font,v,x+dx,y+dy,w,lines);}
 private void renderWelcome(GuiGraphics g){text(g,"Спасибо, что скачали Кэл.",25,43,132,3);text(g,"За тихими деревнями стоят пустые города. В книгах ещё видны следы чужого дыхания, а оставленные механизмы ждут голоса, который больше не вернётся.",25,78,132,10);text(g,"Собирайте строки Кэл — и решайте, какие слова стоит произносить снова.",196,43,132,5);text(g,"Закладки ведут к словам и уцелевшим вещам. Бумага позволит записать вопрос; обычное действие оставит на ней первую мысль.",196,99,132,8);}
 private void renderWords(GuiGraphics g,int mx,int my){if(knownOnly&&known.isEmpty()){text(g,"В этой книге пока нет известных слов.",25,63,132,7);text(g,"Я могу раскрыть рукопись и сохранить найденную строку на столе архивариуса.",196,63,132,9);return;}String w=WORDS.get(page);boolean has=known.contains(w);text(g,has?w:"Нерасшифрованная страница",25,47,132,2);if(has){var glyph=Component.literal(GlyphWriting.write(w)).withStyle(Style.EMPTY.withFont(ResourceLocation.fromNamespaceAndPath(KelMagic.MODID,"kel")));g.drawString(font,glyph,x+48,y+67,0x386E78,false);text(g,"Значение: "+KelLexicon.WORDS.get(w).translation(),25,91,132,2);text(g,WordRarity.label(w),25,118,132,1);var lines=font.split(Component.literal(SpellProfiles.describe(w)),132);for(int i=0;i<Math.min(5,lines.size());i++){if(i==4&&lines.size()>5)g.drawString(font,"… наведите курсор",x+25,y+132+i*9,CodexPaint.INK,false);else g.drawString(font,lines.get(i),x+25,y+132+i*9,CodexPaint.INK,false);}text(g,"Заметка архивариуса",196,49,132,2);text(g,"То, как я понимаю это слово:",196,73,132,3);g.fill(x+194,y+115,x+334,y+137,0xFFDBC392);g.fill(x+194,y+137,x+334,y+138,0xFFA88760);text(g,"Хранится в книге.",196,141,132,1);if(tableView!=null)text(g,notes.get(page).isBlank()?"Заметок пока нет.":notes.get(page),196,113,132,3);if(mx>=x+25&&mx<x+157&&my>=y+132&&my<y+180)tooltip(g,List.of(Component.literal(SpellProfiles.describe(w))),mx,my);}else{text(g,"Найдите древнюю рукопись, раскройте её и соедините полученный лист с кодексом на столе архивариуса.",25,80,132,10);text(g,"Здесь пока лишь следы чернил. Слова обретают смысл в руках читателя.",196,62,132,10);}}
 public List<ResearchCatalog.Node> graphNodes(){var all=ResearchCatalog.NODES.stream().filter(n->n.tab().equals(TABS[section])).toList();var available=new HashSet<String>();for(var n:all)if(eligible(n))available.add(n.id());return all.stream().filter(this::eligible).toList();}
 private boolean ideaWordKnown(ResearchCatalog.Node n){String w=Research.requiredWord(n);return w.isEmpty()||known.contains(w)||Minecraft.getInstance().player!=null&&Research.inventoryWords(Minecraft.getInstance().player).contains(w);}
 private boolean eligible(ResearchCatalog.Node n){return ResearchCatalog.learned(ResearchClient.state,n.id())||ResearchClient.state.started().contains(n.id())||n.parents().stream().allMatch(v->ResearchCatalog.learned(ResearchClient.state,v));}
 private int nx(ResearchCatalog.Node n){return x+180+panX+(int)Math.round(n.x()*zoom);}private int ny(ResearchCatalog.Node n){return y+106+panY+(int)Math.round(n.y()*zoom);}
 static String nodeName(ResearchCatalog.Node n){if(n.id().startsWith("rite:"))return Component.translatable("advancements.kelmagic.rite_"+n.id().substring(5)+".title").getString();return Research.name(n);}
 /** Stationary chapter art; only overlaid motes and waves move. Zoom affects the graph alone. */
 private void background(GuiGraphics g,long now){int[] bases={0xFF233639,0xFF352C3C,0xFF263D3A,0xFF243B48,0xFF342D48,0xFF3E302D,0xFF211C39,0xFF352C3C,0xFF24413F};int[] light={0xFF79B6B0,0xFFC1A97C,0xFFE2BC69,0xFF76C7D2,0xFFA791D4,0xFFD38D62,0xFFAE97DF,0xFFC1A97C,0xFF6ED4C3};int base=bases[section],glow=light[section];g.fill(x+10,y+18,x+350,y+200,base);double t=now/1000.;scissor(g,x+10,y+18,x+350,y+200);var texture=ResourceLocation.fromNamespaceAndPath(KelMagic.MODID,"textures/gui/research/"+TABS[section]+".png");int ox=0,oy=0;for(int tx=0;tx<3;tx++)for(int ty=0;ty<2;ty++)g.blit(texture,x+10+tx*256-ox,y+18+ty*256-oy,0,0,256,256,256,256);for(int i=0;i<70;i++){int xx=x+10+Math.floorMod(i*79+(int)(t*(section==3?2.2:1.2)%340),340),yy=y+18+Math.floorMod(i*47+(int)(t*.7%180),180);int a=(int)(25+24*(1+Math.sin(t*.6+i)));g.fill(xx,yy,xx+(i%13==0?2:1),yy+1,(glow&0xFFFFFF)|(a<<24));if(i%13==0)g.fill(xx,yy-1,xx+1,yy+2,(glow&0xFFFFFF)|0x28000000);}disableScissor(g);}
 private void disableScissor(GuiGraphics g){if(tableView!=null){g.flush();com.mojang.blaze3d.systems.RenderSystem.disableScissor();}else g.disableScissor();}
 private void scissor(GuiGraphics g,int left,int top,int right,int bottom){if(tableView!=null){g.flush();com.mojang.blaze3d.systems.RenderSystem.enableScissor(left*TableBookView.SCALE,(TableBookView.HEIGHT-bottom)*TableBookView.SCALE,(right-left)*TableBookView.SCALE,(bottom-top)*TableBookView.SCALE);return;}g.enableScissor((int)(left*uiScale),(int)(top*uiScale),(int)Math.ceil(right*uiScale),(int)Math.ceil(bottom*uiScale));}
 private void tooltip(GuiGraphics g,List<Component> tip,int mx,int my){if(tableView!=null){TableBookView.tooltip(g,font,tip,mx,my);return;}g.pose().popPose();g.renderTooltip(font,tip,Optional.empty(),(int)(mx*uiScale),(int)(my*uiScale));g.pose().pushPose();g.pose().scale(uiScale,uiScale,1);}
 private void wave(GuiGraphics g,int ax,int ay,int bx,int by,long now,boolean locked){double dx=bx-ax,dy=by-ay,len=Math.max(1,Math.hypot(dx,dy)),px=-dy/len,py=dx/len;int count=(int)Math.max(12,len*2);double t=now/1000.;for(int i=0;i<=count;i++){double f=(double)i/count,offset=Math.sin(f*Math.PI)*Math.sin(f*Math.PI*3-t*.8)*3.5;int xx=(int)(ax+dx*f+px*offset),yy=(int)(ay+dy*f+py*offset);int color=locked?0x80596B70:0xD888C5B6;g.fill(xx,yy,xx+2,yy+2,color);if(!locked&&Math.abs(f-(t*.09%1))<.025)g.fill(xx-1,yy-1,xx+2,yy+2,0xFFCFE5B8);}}
 private void renderMap(GuiGraphics g,int mx,int my,long now){background(g,now);var nodes=graphNodes();ResearchCatalog.Node hovered=null;scissor(g,x+10,y+18,x+350,y+200);for(var n:nodes)for(String parent:n.parents()){var from=nodes.stream().filter(p->p.id().equals(parent)).findFirst().orElse(null);if(from!=null)wave(g,nx(from),ny(from),nx(n),ny(n),now,!eligible(n));}for(var n:nodes){int xx=nx(n),yy=ny(n);g.pose().pushPose();g.pose().translate(xx,yy,0);g.pose().scale((float)zoom,(float)zoom,1);g.pose().translate(-xx,-yy,0);boolean learned=ResearchCatalog.learned(ResearchClient.state,n.id()),active=ResearchClient.state.started().contains(n.id()),available=eligible(n)&&!n.sealed()&&ideaWordKnown(n);boolean locked=!learned&&!active&&!available;int edge=learned?0xFFD5B577:locked?0xFF55545F:active?0xFF70C3C5:0xFFCFA580;g.fill(xx-16,yy-16,xx+16,yy+16,edge);g.fill(xx-14,yy-14,xx+14,yy+14,locked?0xFF24232D:0xFF48333C);g.renderItem(CodexPaint.icon(n.icon()),xx-8,yy-8);if(locked){g.fill(xx-13,yy-11,xx+13,yy+11,0x850C111C);g.fill(xx+9,yy+7,xx+13,yy+12,0xFF84908C);g.fill(xx+10,yy+4,xx+12,yy+8,0xFF84908C);}else if(active&&!learned){int done=Research.progress(ResearchClient.state,n);for(int j=0;j<n.steps().size();j++)g.fill(xx-10+j*7,yy+11,xx-6+j*7,yy+13,j<done?0xFFDFCF85:0xFF5C6666);}if(active&&!learned){g.fill(xx-12,yy+18,xx+12,yy+29,0xC0223135);g.drawCenteredString(font,Research.progress(ResearchClient.state,n)+"/"+n.steps().size(),xx,yy+20,0xFFAFDED5);}g.pose().popPose();if(Math.abs(mx-xx)<=17*zoom&&Math.abs(my-yy)<=17*zoom)hovered=n;}disableScissor(g);if(hovered!=null&&mx>x+10&&mx<x+350&&my>y+18&&my<y+200){var tip=new ArrayList<Component>();tip.add(Component.literal(nodeName(hovered)));if(ResearchCatalog.learned(ResearchClient.state,hovered.id()))tip.add(Component.literal("Открыть страницы записи").withStyle(net.minecraft.ChatFormatting.GRAY));else if(ResearchClient.state.started().contains(hovered.id())){int done=Research.progress(ResearchClient.state,hovered);tip.add(Component.literal("Наблюдения: "+done+"/"+hovered.steps().size()).withStyle(net.minecraft.ChatFormatting.AQUA));tip.add(Component.literal("Открыть лист гипотезы").withStyle(net.minecraft.ChatFormatting.GRAY));}else if(!eligible(hovered))tip.add(Component.literal("Сначала понять: "+String.join(", ",hovered.parents().stream().filter(v->!ResearchCatalog.learned(ResearchClient.state,v)).map(v->nodeName(ResearchCatalog.BY_ID.get(v))).toList())).withStyle(net.minecraft.ChatFormatting.GRAY));else if(hovered.sealed())tip.add(Component.literal("Способ чтения ещё неизвестен").withStyle(net.minecraft.ChatFormatting.GRAY));else if(!ideaWordKnown(hovered))tip.add(Component.literal("У меня пока нет мыслей на этот счёт").withStyle(net.minecraft.ChatFormatting.GRAY));else{int done=Research.progress(ResearchClient.state,hovered);tip.add(Component.literal("Наблюдения: "+done+"/"+hovered.steps().size()).withStyle(net.minecraft.ChatFormatting.AQUA));tip.add(Component.literal(ResearchClient.state.started().contains(hovered.id())?"Открыть лист гипотезы":"Один лист бумаги — записать гипотезу").withStyle(net.minecraft.ChatFormatting.GRAY));}tooltip(g,tip,mx,my);}}
 @Override public boolean mouseClicked(double mx,double my,int button){mx/=uiScale;my/=uiScale;if(super.mouseClicked(mx,my,button))return true;if(section!=0&&section!=7&&button==0&&mx>x+10&&mx<x+350&&my>y+18&&my<y+200){for(var n:graphNodes())if(Math.abs(mx-nx(n))<=17*zoom&&Math.abs(my-ny(n))<=17*zoom){if(!eligible(n))return true;boolean learned=ResearchCatalog.learned(ResearchClient.state,n.id());if(learned||ResearchClient.state.started().contains(n.id())){saveNote();if(tableView!=null)tableView.openEntry(this,n);else Minecraft.getInstance().setScreen(new ResearchEntryScreen(this,n));}else if(!n.sealed()&&ideaWordKnown(n)){if(tableView!=null)tableView.begin(n.id());else PacketDistributor.sendToServer(new ResearchAction(offhand,token,n.id()));}return true;}dragging=true;return true;}return false;}
 @Override public boolean mouseDragged(double mx,double my,int b,double dx,double dy){mx/=uiScale;my/=uiScale;dx/=uiScale;dy/=uiScale;if(dragging&&b==0){panX=Math.clamp(panX+(int)dx,-1200,1200);panY=Math.clamp(panY+(int)dy,-1200,1200);return true;}return super.mouseDragged(mx,my,b,dx,dy);}
 @Override public boolean mouseReleased(double mx,double my,int button){mx/=uiScale;my/=uiScale;dragging=false;return super.mouseReleased(mx,my,button);}
 @Override public boolean mouseScrolled(double mx,double my,double horizontal,double vertical){mx/=uiScale;my/=uiScale;if(section!=0&&section!=7){if(mx<x+10||mx>x+350||my<y+18||my>y+200)return false;double next=Math.clamp(zoom*Math.pow(1.15,vertical),.55,2.2),factor=next/zoom;panX=(int)Math.round(mx-(x+180)-(mx-(x+180)-panX)*factor);panY=(int)Math.round(my-(y+106)-(my-(y+106)-panY)*factor);zoom=next;return true;}return super.mouseScrolled(mx,my,horizontal,vertical);}
 @Override public void removed(){if(tableView!=null)return;saveNote();PacketDistributor.sendToServer(new CodexPosition(offhand,token,section,page,query,sort,knownOnly));super.removed();}
 @Override public boolean isPauseScreen(){return false;}
}
